describe('ToolRegistry', () => {
  it('throws synchronously from register naming the tool when a static inputSchema is invalid', () => {
    const registry = new ToolRegistry();
    const invalidTool = {
      name: 'lookup_order',
      description: 'Look up an order',
      inputSchema: {type: 'unknown-json-schema-type'},
    };

    expect(() => registry.register(invalidTool, async () => 'unused')).toThrow('lookup_order');
  });
});

